#include "carry_queued_abort.hpp"
#include <cstdio>
#include <initializer_list>
using namespace mgscoop::carry_queued_abort;
unsigned good=0,bad=0;void Check(bool ok,const char* name){if(ok)++good;else{++bad;std::printf("FAIL %s\n",name);}}
constexpr std::uintptr_t Image=0x140000000;constexpr std::size_t Span=0xa01d000;
Scope Fixture(unsigned c=0,std::uint8_t prior=0x10){Scope s{};auto& l=s.expected.lease;l.mission=30050;l.generation=3;l.thread=9;l.transaction=5;l.revision=7;l.epoch=2;l.carrier=static_cast<std::uint8_t>(c);l.recipient=static_cast<std::uint8_t>(1-c);l.cause=1;l.player=0x10000;l.carrierRecord=0x70000+c*0x1000;l.recipientPhase=0xd0030+(1-c)*0x1000;
 s.expected.queue=0x20000;s.expected.array=0x40000;s.expected.slot=s.expected.array+l.recipient*0x40;s.current=s.expected;s.windowBody=l.recipient;s.priorSequence=s.committedSequence=prior;
 s.exactGate=s.serializedNaturalWindow=s.typedAllocation=s.coherentNativeStates=s.deferredQueueQuiesced=s.controlsRetained=true;
 mgscoop::carry_request_payload::BuildRecipient(Image,Span,c,1-c,prior,s.ours);s.ours.force=0;s.observed=s.ours;s.carrierActive=true;s.carrierCurrent=s.carrierNext=1;s.carrierProgress=2;s.carrierOfflineOwned=1;s.carrierVariant=0xa;s.carrierOwner=static_cast<std::uint16_t>(c);s.carrierTarget=s.carrierPrevious=static_cast<std::uint16_t>(1-c);return s;
}
int main(){Token t{};NeutralRequest n{};auto s=Fixture();Check(Plan(Image,Span,s,t,n)==Reason::plan,"queued unconsumed request nomination");Check(n.vtable==Image+mgscoop::carry_request_retirement::kNeutralVtableRva&&n.kind==0,"neutral typed 16-byte request");Check(!t.confirmed&&!t.endNominated,"plan does not imply native write or End");
 CarrierEndScope end{s,n,true,false};end.fresh.windowBody=end.fresh.expected.lease.carrier;Check(!NominateCarrierEnd(Image,Span,end,t),"no End before readback");Check(Confirm(Image,Span,s,n,t),"fresh neutral readback confirms");Check(!NominateCarrierEnd(Image,Span,end,t),"unqualified End refused even after neutral");end.fullyQualifiedEnd=true;Check(NominateCarrierEnd(Image,Span,end,t),"only qualified fresh carrier End nominated");Check(!NominateCarrierEnd(Image,Span,end,t),"duplicate End refused");Check(!Confirm(Image,Span,s,n,t),"duplicate confirmation refused");Check(Plan(Image,Span,s,t,n)==Reason::duplicate&&!n.vtable,"duplicate neutral nomination refused");
 for(auto member:{&Scope::exactGate,&Scope::serializedNaturalWindow,&Scope::typedAllocation,&Scope::coherentNativeStates,&Scope::deferredQueueQuiesced,&Scope::controlsRetained}){s=Fixture();s.*member=false;t={};Check(Plan(Image,Span,s,t,n)==Reason::scope&&!n.vtable&&!t.planned,"missing proof prevents any nomination");}
 for(unsigned k=0;k<12;++k){s=Fixture();switch(k){case 0:s.current.lease.generation++;break;case 1:s.current.lease.epoch++;break;case 2:s.current.lease.revision++;break;case 3:s.current.lease.thread++;break;case 4:s.current.lease.transaction++;break;case 5:s.current.queue+=8;break;case 6:s.current.array+=0x80;break;case 7:s.current.slot+=0x40;break;case 8:s.current.lease.carrierRecord+=0x1000;break;case 9:s.expected.lease.transaction=s.current.lease.transaction=0;break;case 10:s.expected.lease.mission=s.current.lease.mission=10010;break;default:s.expected.slot=s.current.slot=UINTPTR_MAX-15;break;}t={};Check(Plan(Image,Span,s,t,n)==Reason::identity&&!n.vtable,"replaced typed lease refuses");}
 for(unsigned k=0;k<9;++k){s=Fixture();switch(k){case 0:s.observed.sequence++;break;case 1:s.observed.kind=0;break;case 2:s.observed.carrier=1;break;case 3:s.ours.force=s.observed.force=1;break;case 4:s.ours.substate=s.observed.substate=4;break;case 5:s.ours.reserved08[1]=s.observed.reserved08[1]=1;break;case 6:s.ours.additional=s.observed.additional=-0.0f;break;case 7:s.committedSequence=s.ours.sequence;break;default:s.priorSequence=s.committedSequence=0x20;break;}t={};Check(Plan(Image,Span,s,t,n)==Reason::payload&&!n.vtable,"foreign or consumed sequence request refused");}
 for(unsigned k=0;k<8;++k){s=Fixture();switch(k){case 0:s.recipientActive=true;break;case 1:s.recipientEndPending=true;break;case 2:s.recipientCurrent=1;break;case 3:s.recipientNext=1;break;case 4:s.recipientCarrierRecord=s.expected.lease.carrierRecord;break;case 5:s.recipientResource=0x10000;break;case 6:s.recipientCarrier=0;break;default:s.committedSequence++;break;}t={};const auto reason=Plan(Image,Span,s,t,n);Check(reason==Reason::consumed||reason==Reason::payload,"recipient initialization or binding cannot be neutralized by this policy");}
 for(unsigned k=0;k<11;++k){s=Fixture();switch(k){case 0:s.carrierActive=false;break;case 1:s.carrierEndPending=true;break;case 2:s.carrierCurrent=4;break;case 3:s.carrierNext=6;break;case 4:s.carrierProgress=4;break;case 5:s.carrierAck=1;break;case 6:s.carrierCancel=1;break;case 7:s.carrierOfflineOwned=0;break;case 8:s.carrierVariant=9;break;case 9:s.carrierOwner=0xffff;break;default:s.carrierPrevious=0xffff;break;}t={};Check(Plan(Image,Span,s,t,n)==Reason::carrier&&!n.vtable,"only exact owned force-A initial handshake allowed");}
 for(auto prior:{std::uint8_t{0},std::uint8_t{0xfa},std::uint8_t{0xff}}){s=Fixture(1,prior);t={};Check(Plan(Image,Span,s,t,n)==Reason::plan,"both role and sequence-wrap ordering");}
 s=Fixture();t={};Check(Plan(Image,Span,s,t,n)==Reason::plan,"stale checks setup");auto wrong=n;wrong.reserved[3]=1;Check(!Confirm(Image,Span,s,wrong,t),"partial neutral write refused");s.current.lease.generation++;Check(!Confirm(Image,Span,s,n,t),"generation loss before readback refused");s=Fixture();Check(Confirm(Image,Span,s,n,t),"valid readback after refused attempts");end={s,n,true,true};end.fresh.windowBody=end.fresh.expected.lease.carrier;end.fresh.recipientNext=1;Check(!NominateCarrierEnd(Image,Span,end,t),"recipient race after neutral refuses End");end={s,n,true,true};end.fresh.windowBody=end.fresh.expected.lease.carrier;end.fresh.current.queue+=8;Check(!NominateCarrierEnd(Image,Span,end,t),"Q replacement before End refused");end={s,n,false,true};end.fresh.windowBody=end.fresh.expected.lease.carrier;Check(!NominateCarrierEnd(Image,Span,end,t),"natural carrier window required");Forget(t);Check(!t.planned&&!t.confirmed&&!t.endNominated&&!t.identity.queue,"lease loss forgets mod state only");
 s=Fixture();t={};Check(Plan(Image,0x1000,s,t,n)==Reason::payload,"short exact image refused");Check(Plan(UINTPTR_MAX-7,Span,s,t,n)==Reason::payload,"overflow image refused");std::printf("%u passed, %u failed\n",good,bad);return bad?1:0;
}
